233			if j.status == StatusSucceeded && !archiveIntact(j) {
234				j.status = StatusFailed
235				j.failureReason = "归档不完整或校验值不一致，成功结果不可用"
236				if j.finishedAt.IsZero() {
237					j.finishedAt = time.Now().UTC()
238				}
239				j.effectiveValues = nil
240				j.archive = nil
241				if data, err := encodeRecord(j); err == nil {
242					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
243				}
244			}
245			jobs = append(jobs, j)
246			if j.id > maxID {
