552		s, _ := openTestStore(t)
553		started, block, release, _, _ := gateCompute(t, s)
554		block(1)
555	
556		first := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
557		waitStarted(t, started, first.ID)
558	
559		mid := mustSubmit(t, s, SubmitRequest{ // 等 first 的结果
560			Submitter: "a", Values: []int64{2},
561			HasDependency: true, DependencyID: first.ID,
562		})
563		far := mustSubmit(t, s, SubmitRequest{ // 等 mid
564			Submitter: "a", Values: []int64{3},
565			HasDependency: true, DependencyID: mid.ID,
566		})
567		independent := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{9}})
568		// 此时唯一位置被 id 1 占用，mid/far 等依赖、independent 等位置。
