571		cj, err := s.Cancel(first.ID)
572		if err != nil || cj.Status != StatusCanceled {
573			t.Fatalf("cancel running: %v %+v", err, cj)
574		}
575		// 重复取消仍成功。
576		if again, err := s.Cancel(first.ID); err != nil || again.Status != StatusCanceled {
577			t.Fatalf("repeat cancel: %v %+v", err, again)
578		}
579		release(first.ID) // 放行计算，成功结果必须被丢弃
580	
581		mm := waitStatus(t, s, mid.ID, StatusFailed)
582		ff := waitStatus(t, s, far.ID, StatusFailed)
583		// independent 未被等待依赖的 mid/far 堵在后面，照常成功。
584		ind := waitStatus(t, s, independent.ID, StatusSucceeded)
585		if ind.Archive.Sum != 9 {
