587		}
588		if mm.BlockerID != first.ID || ff.BlockerID != first.ID {
589			t.Fatalf("cascade blockers %d,%d want root %d", mm.BlockerID, ff.BlockerID, first.ID)
590		}
591		if mm.Archive != nil || ff.Archive != nil {
592			t.Fatal("canceled job and dependents must never archive success")
593		}
594		if !strings.Contains(mm.FailureReason, "取消") || !strings.Contains(ff.FailureReason, "阻断") {
595			t.Fatalf("failure reasons must explain the blocker: mid=%q far=%q", mm.FailureReason, ff.FailureReason)
596		}
597	
598		// 已成功的作业不能取消，结果保持。
599		if _, err := s.Cancel(independent.ID); !errors.Is(err, ErrNotCancellable) {
600			t.Fatalf("cancel succeeded: %v, want ErrNotCancellable", err)
