func pendingDependenciesLocked(j *storedJob, byID map[uint64]*storedJob) []uint64 {
	var pending []uint64
	for _, depID := range j.dependencies {
		dep := byID[depID]
		if dep == nil || dep.status != StatusSucceeded {
